game.initial-sql-script:
-- Create database --CREATE DATABASE test;
-- Connect to the new database -- \c test
-- Create schemas
-- Create table in schema b first (referenced by foreign key) CREATE TABLE table_b ( id_b SERIAL PRIMARY KEY, some_value TEXT NOT NULL );
-- Create table in schema a with foreign key to table_b CREATE TABLE table_a ( id_a SERIAL PRIMARY KEY, some_value TEXT NOT NULL, fk_id_b INT NOT NULL REFERENCES table_b(id_b) );
-- Insert data into table_b first INSERT INTO table_b (some_value) VALUES ('hello from b'), ('another b value'), ('yet another b');
-- Insert data into table_a referencing table_b rows INSERT INTO table_a (some_value, fk_id_b) VALUES ('hello from a', 1), ('another a value', 2), ('yet another a', 3);
